package com.dev2go.core

import java.util.Base64

/**
 * opencode's server authentication.
 *
 * Not optional and not a token: `opencode serve` always generates a password if
 * `OPENCODE_PASSWORD` is unset, and the server rejects unauthenticated requests with 401 —
 * confirmed against a live server. The client sends HTTP Basic with the username `opencode`
 * and that password as the value.
 *
 * The password is generated by the app and passed to the child process's environment, so
 * it never crosses the network and never needs storing.
 */
object ServerAuth {

    const val USERNAME = "opencode"

    /** `Authorization: Basic ...` for the given password. */
    fun header(password: String): String =
        "Basic " + Base64.getEncoder().encodeToString("$USERNAME:$password".toByteArray())

    /**
     * A password for the child process.
     *
     * 32 random bytes, base64url — the same shape opencode uses for its own generated
     * password. Entropy matters here because the server binds to loopback but any app on
     * the device can reach that port, so this is what stops another app driving the agent.
     */
    fun generatePassword(): String {
        val bytes = ByteArray(32)
        java.security.SecureRandom().nextBytes(bytes)
        return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes)
    }
}